export declare const campaignFinished = "\n<!DOCTYPE html>\n<html lang=\"fr\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Campagne Termin\u00E9e</title>\n\n<style>\nbody{margin:0;padding:0;background:#f3f4f6;font-family:Arial;color:#111827;}\n.wrapper{width:100%;padding:40px 20px;box-sizing:border-box;}\n.container{max-width:620px;margin:0 auto;background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;}\n.header{padding:28px 32px;border-bottom:1px solid #e5e7eb;}\n.header h1{margin:0;font-size:22px;font-weight:600;}\n.content{padding:32px;}\n.alert-box{margin:28px 0;border:1px solid #e5e7eb;background:#f9fafb;border-radius:8px;}\n.info-row{display:flex;padding:14px 18px;border-bottom:1px solid #e5e7eb;}\n.info-row:last-child{border-bottom:none;}\n.label{width:190px;font-weight:600;}\n.value{flex:1;}\n.notice{margin-top:30px;padding-top:20px;border-top:1px solid #e5e7eb;font-size:14px;color:#6b7280;}\n.footer{padding:20px 32px;background:#f9fafb;text-align:center;font-size:12px;color:#9ca3af;}\n</style>\n\n</head>\n\n<body>\n<div class=\"wrapper\">\n<div class=\"container\">\n\n<div class=\"header\">\n<h1>Rapport campagne termin\u00E9</h1>\n</div>\n\n<div class=\"content\">\n\n<p>Votre campagne est termin\u00E9e.</p>\n\n<div class=\"alert-box\">\n<div class=\"info-row\"><div class=\"label\">Campagne</div><div class=\"value\">%campaign_name%</div></div>\n<div class=\"info-row\"><div class=\"label\">Envoy\u00E9s</div><div class=\"value\">%total_sent%</div></div>\n<div class=\"info-row\"><div class=\"label\">Livr\u00E9s</div><div class=\"value\">%total_delivered%</div></div>\n<div class=\"info-row\"><div class=\"label\">\u00C9chou\u00E9s</div><div class=\"value\">%total_failed%</div></div>\n<div class=\"info-row\"><div class=\"label\">Co\u00FBt final</div><div class=\"value\">%final_cost%</div></div>\n<div class=\"info-row\"><div class=\"label\">Rapport</div><div class=\"value\">%report_url%</div></div>\n</div>\n\n</div>\n\n<div class=\"notice\">\nRapport g\u00E9n\u00E9r\u00E9 automatiquement apr\u00E8s ex\u00E9cution compl\u00E8te.\n</div>\n\n<div class=\"footer\">\n\u00A9 %current_year% SaaS SMS Platform\n</div>\n\n</div>\n</div>\n</body>\n</html>\n";
